style.css:
@-moz-document domain("www.bankofamerica.com"), domain("secure.bankofamerica.com"), url-prefix("https://bankofamerica.com/") {
/* Legacy secure banking uses additional wrappers and locally styled text.
   Clear structural fills first; component rules below supply the glass panels. */
html body div, html body section, html body article, html body form,
html body ul, html body ol, html body li, html body fieldset {
  background-color: transparent !important;
}
html body div, html body p, html body li, html body td,
html body label, html body strong, html body em, html body small,
html body span:not([class*="icon"]):not([class*="Icon"]):not([aria-hidden="true"]) {
  color: #c5ccd8 !important;
}
html body div, html body span:not([class*="icon"]):not([class*="Icon"]):not([aria-hidden="true"]),
html body a, html body strong, html body em, html body small {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
}
/* Canvas: reference 40px grid and 4px scanlines, recolored cool blue. */
html {
  color-scheme: dark !important;
  background-color: #0a0a0a !important;
  background-image: linear-gradient(to right, rgba(130,174,255,.13) 1px, transparent 1px), linear-gradient(to bottom, rgba(130,174,255,.13) 1px, transparent 1px), repeating-linear-gradient(to bottom, rgba(10,10,10,0) 0px, rgba(10,10,10,0) 3px, rgba(105,160,255,.035) 3px, rgba(105,160,255,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
  scrollbar-color: #536c98 #081020 !important;
  scrollbar-width: thin !important;
}
body, body.spa-site-homepage, #root, #app, #__next, #wrapper, #page, #pageContainer,
#main, #mainContent, main, .spa-layout-container, .sparta-layout, .flex-grid-layout,
.masthead-container-module, .masthead-children, .highlight-lowlight-module,
.highlight-lowlight-container, .content--wrapper, #bmhModule, #bmhContainer,
#newsInformationModule, #connectWithUsModule {
  background-color: transparent !important;
  background-image: none !important;
  color: #c5ccd8 !important;
}
html, body, p, li, dt, dd, label, legend, caption, th, td,
h1, h2, h3, h4, h5, h6, input, textarea, select, button,
nav, header, footer, aside, article, section, summary,
[role="button"], [role="tab"], [role="menu"], [role="dialog"],
.spa-btn, .title, .heading, .subheading, .text-box {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
}
body { color: #c5ccd8 !important; }
p, label, legend, dt, dd, caption, li, td, .text-box, .content, .spa-card__body {
  color: #c5ccd8 !important;
}
h1, h2, h3, h4, h5, h6, .heading, .title, .subheading, .spa-card__title {
  color: #d1d7e1 !important;
  text-shadow: 0 0 12px rgba(85,136,227,.18) !important;
}
small, .disclaimer, .trademark-disclosure, .footnote, .secondary,
.spa-input-hint, .muted, .text-muted, [class~="legal"] {
